window.CONSTITUTION_DATA = {"id":"constitution","title":"Конституция РО","full_title":"Конституция РО","revision":"18.09.2026","source_url":"https://forum.russia.online/threads/konstitutsiya-ro.4707/","post_id":"post-16034","preamble":"Мы, граждане РО, утверждая законность, справедливость, общественную безопасность и взаимную ответственность государства и гражданина, принимаем настоящую Конституцию как основной закон РО.","signature":"Нормативно-правовой акт подписан Премьер-министром РО 18.09.2026 Марк Брагин ​","type_detected":"D","nodes":[{"type":"chapter","number":"I","title":"Основы государственного и правового устройства","children":[{"type":"article","number":"1","title":"РО","children":[{"type":"paragraph","number":"1","text":"РО — демократическое и правовое государство, государственная власть в котором осуществляется в соответствии с настоящей Конституцией и федеральным законодательством."},{"type":"paragraph","number":"2","text":"Наименования «РО» и «Российский округ» равнозначны."}]},{"type":"article","number":"2","title":"Человек, его права и свободы","children":[{"type":"paragraph","number":"1","text":"Человек, его права и свободы являются высшей ценностью. Признание, соблюдение и защита прав и свобод человека и гражданина являются обязанностью государства и его должностных лиц."},{"type":"paragraph","number":"2","text":"Государственные полномочия не могут использоваться вопреки их назначению, в личных целях либо для создания необоснованных преимуществ или ограничений."}]},{"type":"article","number":"3","title":"Источник государственной власти","children":[{"type":"paragraph","number":"1","text":"Носителем суверенитета и источником государственной власти является народ РО."},{"type":"paragraph","number":"2","text":"Граждане участвуют в осуществлении государственной власти непосредственно и через государственные органы в порядке, установленном законодательством."},{"type":"paragraph","number":"3","text":"Присвоение полномочий государственного органа или должностного лица запрещается."}]},{"type":"article","number":"4","title":"Организация государственной власти","children":[{"type":"paragraph","number":"1","text":"Государственная власть организуется на основе разграничения полномочий между Премьер-министром РО, Государственной Думой РО, Правительством РО, судами, прокуратурой, Следственным комитетом и правоохранительными органами."},{"type":"paragraph","number":"2","text":"Государственная Дума РО осуществляет законодательную власть. Правительство РО является высшим коллегиальным исполнительным органом государственного управления."},{"type":"paragraph","number":"3","text":"Судебная власть самостоятельна при осуществлении правосудия. Правительство и Премьер-министр не вправе вмешиваться в рассмотрение конкретного судебного дела иначе как в формах, прямо предусмотренных законом."},{"type":"paragraph","number":"4","text":"Правительство и Премьер-министр не вправе вмешиваться в расследование конкретного уголовного дела или оперативно-розыскную деятельность правоохранительных органов, кроме случаев и процедур, прямо предусмотренных федеральным законодательством."}]},{"type":"article","number":"5","title":"Территория РО","children":[{"type":"paragraph","number":"1","text":"Суверенитет РО распространяется на всю территорию государства."},{"type":"paragraph","number":"2","text":"Порядок определения административных и муниципальных территорий, режимных объектов, охраняемых зон и иных территорий устанавливается федеральным законодательством."}]},{"type":"article","number":"6","title":"Законность","children":[{"type":"paragraph","number":"1","text":"Органы государственной власти, государственные организации, должностные лица и граждане обязаны соблюдать Конституцию и действующее законодательство."},{"type":"paragraph","number":"2","text":"Государственный служащий вправе осуществлять только те полномочия, которые предоставлены ему законом, актом компетентного органа либо законным поручением вышестоящего должностного лица."},{"type":"paragraph","number":"3","text":"Заведомо незаконный приказ или распоряжение не подлежит исполнению в случаях и порядке, установленных федеральным законодательством."}]},{"type":"article","number":"7","title":"Иерархия нормативных правовых актов","children":[{"type":"paragraph","number":"1","text":"В РО устанавливается следующая иерархия нормативных правовых актов: Конституция РО; Федеральные конституционные законы; Кодексы и федеральные законы; Нормативные указы Премьер-министра РО; Постановления и распоряжения Правительства РО а равно как Вице Премьер-министра; Нормативные акты министерств и иных федеральных органов; Внутренние акты государственных организаций."},{"type":"paragraph","number":"2","text":"Акт нижестоящей юридической силы не может противоречить акту вышестоящей юридической силы."},{"type":"paragraph","number":"3","text":"Внутренний регламент, инструкция, приказ подразделения или иной локальный акт не может самостоятельно устанавливать для граждан новые обязанности, запреты, составы правонарушений или наказания."}]},{"type":"article","number":"8","title":"Законодательное регулирование","children":[{"type":"paragraph","number":"1","text":"Федеральные законы и кодексы принимаются Государственной Думой РО в коллегиальном порядке и вступают в силу после утверждения и официального опубликования в порядке, установленном настоящей Конституцией и федеральным законодательством."},{"type":"paragraph","number":"2","text":"Государственная Дума обеспечивает развитие и актуальность законодательной базы. Правительство, суды, прокуратура, Следственный комитет и иные государственные органы вправе вносить предложения об устранении противоречий, пробелов и устаревших норм в пределах своей компетенции."},{"type":"paragraph","number":"3","text":"Изменение законодательства не допускается, если оно противоречит настоящей Конституции, установленному разграничению компетенции государственных органов или основным гарантиям прав и свобод."}]},{"type":"article","number":"9","title":"Официальное опубликование","children":[{"type":"paragraph","number":"1","text":"Нормативные акты, затрагивающие права, обязанности, ответственность граждан или компетенцию государственных органов, подлежат официальному опубликованию."},{"type":"paragraph","number":"2","text":"Действующий указ, распоряжение, постановление или иной нормативный акт Премьер-министра либо Правительства должен быть размещён в установленном официальном разделе Правительства на форуме проекта, если федеральным законом не предусмотрен иной способ опубликования."},{"type":"paragraph","number":"3","text":"Неопубликованный нормативный акт, затрагивающий права и обязанности граждан, не подлежит применению, кроме случаев, прямо предусмотренных законом для сведений ограниченного доступа."}]},{"type":"article","number":"10","title":"Судебное толкование","children":[{"type":"paragraph","number":"1","text":"Суд применяет Конституцию и федеральное законодательство при рассмотрении конкретных дел."},{"type":"paragraph","number":"2","text":"Правовая позиция Верховного Суда обязательна для нижестоящих судов и государственных органов в части толкования действующей нормы, но не может самостоятельно устанавливать новый состав преступления или административного правонарушения."},{"type":"paragraph","number":"3","text":"Суд вправе признать нормативный акт или его часть не подлежащими применению при их противоречии Конституции или акту большей юридической силы."}]},{"type":"article","number":"11","title":"Государственные организации и служащие","children":[{"type":"paragraph","number":"1","text":"Статус, компетенция и порядок деятельности государственных организаций определяются Конституцией, федеральными законами и утвержденными в установленном порядке внутренними актами."},{"type":"paragraph","number":"2","text":"Служащие государственных организаций обязаны соблюдать служебную дисциплину, правила идентификации, видеофиксации и иные требования, установленные федеральным законодательством."},{"type":"paragraph","number":"3","text":"Злоупотребление должностными полномочиями и государственным функционалом запрещается и влечет установленную законом ответственность."}]}]},{"type":"chapter","number":"II","title":"Права, свободы и обязанности человека и гражданина​","children":[{"type":"article","number":"12","title":"Равенство перед законом и судом","children":[{"type":"paragraph","number":"1","text":"Все равны перед законом и судом."},{"type":"paragraph","number":"2","text":"Не допускается необоснованное ограничение прав по признакам пола, расы, национальности, происхождения, убеждений, должностного или имущественного положения и иным обстоятельствам, не связанным с законной целью ограничения."}]},{"type":"article","number":"13","title":"Право на жизнь и безопасность","children":[{"type":"paragraph","number":"1","text":"Каждый имеет право на жизнь, личную безопасность и защиту от произвольного применения насилия."},{"type":"paragraph","number":"2","text":"Применение физической силы, специальных средств и оружия государственными служащими допускается только на законном основании, в необходимом объеме и в порядке, установленном федеральным законодательством."}]},{"type":"article","number":"14","title":"Свобода и личная неприкосновенность","children":[{"type":"paragraph","number":"1","text":"Каждый имеет право на свободу и личную неприкосновенность."},{"type":"paragraph","number":"2","text":"Задержание, арест, заключение под стражу и иное принудительное ограничение свободы допускаются исключительно по основаниям и в порядке, предусмотренным федеральным законодательством."}]},{"type":"article","number":"15","title":"Право знать основания задержания","children":[{"type":"paragraph","number":"1","text":"Задержанному лицу должны быть сообщены основание задержания, нарушенные им нормы законодательства и принадлежащие ему процессуальные права."},{"type":"paragraph","number":"2","text":"Права и применяемые нормы должны быть разъяснены ясно и в объёме, достаточном для понимания задержанным существа предъявляемых требований и ограничений."},{"type":"paragraph","number":"3","text":"Порядок и момент разъяснения прав определяются процессуальным законодательством."},{"type":"paragraph","number":"4","text":"Процессуальные действия должны совершаться без необоснованного затягивания. Намеренное увеличение продолжительности задержания или иной процедуры в отсутствие законной необходимости запрещается."}]},{"type":"article","number":"16","title":"Право на защиту и адвоката","children":[{"type":"paragraph","number":"1","text":"Каждому гарантируется право на квалифицированную юридическую помощь."},{"type":"paragraph","number":"2","text":"Задержанному должна быть предоставлена разумная возможность воспользоваться помощью адвоката в порядке, установленном процессуальным законодательством."},{"type":"paragraph","number":"3","text":"Отказ лица от адвоката, а также последствия последующего изменения такого решения регулируются федеральным законом. Отказ должен быть выражен однозначно либо вытекать из поведения лица в случаях, прямо предусмотренных законом."},{"type":"paragraph","number":"4","text":"Государство обеспечивает функционирование механизма вызова государственного или частного адвоката и лицензирования адвокатской деятельности."}]},{"type":"article","number":"17","title":"Презумпция невиновности","children":[{"type":"paragraph","number":"1","text":"Лицо считается невиновным, пока его виновность не установлена в предусмотренном законом порядке."},{"type":"paragraph","number":"2","text":"Обвиняемый не обязан доказывать свою невиновность."},{"type":"paragraph","number":"3","text":"Неустранимые сомнения толкуются в пользу обвиняемого."}]},{"type":"article","number":"18","title":"Недопустимость произвольного обвинения","children":[{"type":"paragraph","number":"1","text":"Возбуждение уголовного дела, предъявление обвинения и применение мер процессуального принуждения допускаются только при наличии установленных законом оснований и достаточных данных."},{"type":"paragraph","number":"2","text":"Фабрикация доказательств, давление на участников процесса и использование заведомо недостоверных сведений запрещаются."}]},{"type":"article","number":"19","title":"Право не свидетельствовать против себя","children":[{"type":"paragraph","number":"1","text":"Никто не обязан свидетельствовать против самого себя, своего супруга и близких родственников, круг которых определяется законом."}]},{"type":"article","number":"20","title":"Недопустимость повторной ответственности","children":[{"type":"paragraph","number":"1","text":"Никто не может быть повторно привлечен к уголовной ответственности за одно и то же деяние после окончательного разрешения вопроса о его виновности."},{"type":"paragraph","number":"2","text":"Привлечение к различным видам ответственности за различные самостоятельные последствия одного поведения допускается только в случаях, прямо установленных законом."}]},{"type":"article","number":"21","title":"Законность доказательств","children":[{"type":"paragraph","number":"1","text":"Доказательства, полученные с существенным нарушением закона, не могут использоваться как единственное или определяющее основание обвинения."},{"type":"paragraph","number":"2","text":"Законность получения и допустимость доказательств подлежат проверке судом."}]},{"type":"article","number":"22","title":"Неприкосновенность частной жизни","children":[{"type":"paragraph","number":"1","text":"Каждый имеет право на неприкосновенность частной жизни, личную и семейную тайну, защиту чести и достоинства."},{"type":"paragraph","number":"2","text":"Сбор, хранение и использование сведений о частной жизни допускаются только на законном основании."}]},{"type":"article","number":"23","title":"Тайна сообщений","children":[{"type":"paragraph","number":"1","text":"Каждый имеет право на тайну переписки, телефонных переговоров и иных сообщений."},{"type":"paragraph","number":"2","text":"Ограничение этого права допускается на основании судебного решения либо в иных прямо предусмотренных федеральным законом случаях с последующим контролем законности."}]},{"type":"article","number":"24","title":"Неприкосновенность жилища и собственности","children":[{"type":"paragraph","number":"1","text":"Жилище и иная законно занимаемая частная территория неприкосновенны."},{"type":"paragraph","number":"2","text":"Проникновение, обыск и выемка допускаются на основании судебного решения, процессуального акта уполномоченного органа либо в неотложных случаях, прямо установленных законом."},{"type":"paragraph","number":"3","text":"Лицо вправе обжаловать законность проведенного обыска или иного вмешательства."}]},{"type":"article","number":"25","title":"Свобода передвижения","children":[{"type":"paragraph","number":"1","text":"Каждый вправе свободно передвигаться по территории РО, за исключением законно установленных режимных, военных, охраняемых и иных территорий с ограниченным доступом."}]},{"type":"article","number":"26","title":"Свобода мысли и слова","children":[{"type":"paragraph","number":"1","text":"Каждому гарантируются свобода мысли и слова."},{"type":"paragraph","number":"2","text":"Осуществление свободы слова не освобождает от ответственности за угрозы, клевету, разглашение охраняемой законом тайны, воспрепятствование правосудию и иные противоправные деяния."}]},{"type":"article","number":"27","title":"Свобода собраний и обращений","children":[{"type":"paragraph","number":"1","text":"Граждане вправе мирно собираться, проводить публичные мероприятия и направлять индивидуальные или коллективные обращения в государственные органы в порядке, установленном законом."}]},{"type":"article","number":"28","title":"Право собственности","children":[{"type":"paragraph","number":"1","text":"Право частной собственности охраняется законом."},{"type":"paragraph","number":"2","text":"Изъятие имущества допускается только на законном основании. Незаконное или беспричинное изъятие имущества государственным служащим запрещается."}]},{"type":"article","number":"29","title":"Право на медицинскую помощь","children":[{"type":"paragraph","number":"1","text":"Каждый имеет право на получение медицинской помощи в порядке, установленном федеральным законодательством."},{"type":"paragraph","number":"2","text":"Экстренная медицинская помощь не может быть произвольно ограничена."}]},{"type":"article","number":"30","title":"Труд и государственная служба","children":[{"type":"paragraph","number":"1","text":"Труд свободен. Каждый вправе выбирать род деятельности в пределах закона."},{"type":"paragraph","number":"2","text":"Граждане имеют право на равный доступ к государственной службе при соблюдении установленных требований."},{"type":"paragraph","number":"3","text":"Порядок назначения, повышения, перевода, понижения и увольнения государственных служащих определяется федеральным законодательством и утвержденными в соответствии с ним кадровыми регламентами."}]},{"type":"article","number":"31","title":"Оружие и специальные средства","children":[{"type":"paragraph","number":"1","text":"Право приобретения, хранения, ношения и использования оружия осуществляется в порядке, установленном федеральным законодательством."},{"type":"paragraph","number":"2","text":"Лицензия или иное разрешение может быть ограничено, приостановлено или отозвано только на законном основании."}]},{"type":"article","number":"32","title":"Судебная защита","children":[{"type":"paragraph","number":"1","text":"Каждому гарантируется судебная защита его прав и свобод."},{"type":"paragraph","number":"2","text":"Решения, действия и бездействие государственных органов и должностных лиц могут быть обжалованы в суд, прокуратуру либо иной уполномоченный орган в порядке, установленном законом."}]},{"type":"article","number":"33","title":"Ограничение прав и обязанности граждан","children":[{"type":"paragraph","number":"1","text":"Права и свободы могут быть ограничены федеральным законом только в объёме, необходимом для защиты прав других лиц, общественного порядка, государственной безопасности, обороны и осуществления правосудия."},{"type":"paragraph","number":"2","text":"Каждый обязан соблюдать законные требования государственных служащих, предъявленные в пределах их компетенции."},{"type":"paragraph","number":"3","text":"Каждый обязан соблюдать Конституцию и федеральное законодательство."}]}]},{"type":"chapter","number":"III","title":"Премьер-министр РО​","children":[{"type":"article","number":"34","title":"Статус Премьер-министра РО","children":[{"type":"paragraph","number":"1","text":"Премьер-министр РО является главой государства, высшим должностным лицом РО и гарантом Конституции, прав и свобод человека и гражданина."},{"type":"paragraph","number":"2","text":"Премьер-министр обеспечивает согласованное функционирование государственных органов и определяет основные направления государственной политики."}]},{"type":"article","number":"35","title":"Полномочия Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр осуществляет общее руководство исполнительной властью в пределах, установленных Конституцией и федеральными законами."},{"type":"paragraph","number":"2","text":"Премьер-министр формирует Правительство, назначает и освобождает от должности членов Правительства и руководителей государственных органов в случаях, предусмотренных законом."},{"type":"paragraph","number":"3","text":"Премьер-министр вправе давать обязательные распоряжения подчиненным ему органам, если такие распоряжения не означают незаконного вмешательства в конкретное уголовное дело, судебное разбирательство или оперативно-розыскное мероприятие."},{"type":"paragraph","number":"4","text":"Премьер-министр осуществляет иные полномочия, предусмотренные Конституцией и федеральным законодательством."}]},{"type":"article","number":"35.1","title":"Вице Премьер-министр","children":[{"type":"paragraph","text":"Вице премьер министр обладает всеми правами, обязанностями и полномочиями Премьер-министра как во время его присутствия, так и во время его отсутствия."}]},{"type":"article","number":"36","title":"Акты Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр издаёт указы и распоряжения."},{"type":"paragraph","number":"2","text":"Акты Премьер-министра обязательны к исполнению на всей территории РО и не могут противоречить Конституции, кодексам и федеральным законам."},{"type":"paragraph","number":"3","text":"Нормативные акты Премьер-министра подлежат официальному опубликованию."}]},{"type":"article","number":"37","title":"Премьер-министр и Правительство","children":[{"type":"paragraph","number":"1","text":"Премьер-министр определяет основные направления деятельности Правительства и вправе председательствовать на его заседаниях."},{"type":"paragraph","number":"2","text":"Правительство подотчетно Премьер-министру по вопросам исполнения государственной политики, но самостоятельно осуществляет коллегиальные полномочия в пределах своей компетенции."}]},{"type":"article","number":"38","title":"Премьер-министр и силовые органы","children":[{"type":"paragraph","number":"1","text":"Федеральная служба безопасности подчиняется Премьер-министру РО и Министру юстиции в пределах их компетенции."},{"type":"paragraph","number":"2","text":"Органы внутренних дел подчиняются Премьер-министру РО и руководству системы Министерства внутренних дел."},{"type":"paragraph","number":"3","text":"Вооруженные Силы подчиняются Премьер-министру РО, Министерству внутренних дел и своему командованию в установленной законом иерархии."}]},{"type":"article","number":"39","title":"Недопустимость вмешательства","children":[{"type":"paragraph","number":"1","text":"Премьер-министр не вправе требовать вынесения конкретного судебного решения, фабрикации доказательств, прекращения или возбуждения уголовного дела без законного основания либо совершения иных действий, нарушающих процессуальную самостоятельность суда, прокуратуры или следственного органа."},{"type":"paragraph","number":"2","text":"Законные формы координации, контроля и поручений определяются федеральным законодательством."}]},{"type":"article","number":"40","title":"Неприкосновенность Премьер-министра","children":[{"type":"paragraph","number":"1","text":"Премьер-министр обладает процессуальной неприкосновенностью в объёме, установленном федеральным законом."},{"type":"paragraph","number":"2","text":"Неприкосновенность является процессуальной гарантией и не означает освобождение от ответственности за совершённое правонарушение."}]},{"type":"article","number":"41","title":"Срок и прекращение полномочий","children":[{"type":"paragraph","number":"1","text":"Срок полномочий Премьер-министра, порядок вступления в должность и порядок досрочного прекращения полномочий устанавливаются федеральным конституционным законом."},{"type":"paragraph","number":"2","text":"Премьер-министр может быть отрешен от должности в случае совершения тяжкого нарушения Конституции или преступления в порядке, установленном федеральным конституционным законом."}]},{"type":"article","number":"42","title":"Временное исполнение обязанностей","children":[{"type":"paragraph","number":"1","text":"При временной невозможности исполнения Премьер-министром своих полномочий их осуществляет должностное лицо, определенное федеральным конституционным законом."},{"type":"paragraph","number":"2","text":"Исполняющий обязанности Премьер-министра не вправе изменять Конституцию или использовать временное положение для незаконного перераспределения полномочий."}]}]},{"type":"chapter","number":"IV","title":"Государственная Дума РО​","children":[{"type":"article","number":"43","title":"Статус Государственной Думы РО","children":[{"type":"paragraph","number":"1","text":"Государственная Дума РО является представительным и законодательным коллегиальным органом государственной власти."},{"type":"paragraph","number":"2","text":"Государственная Дума осуществляет законодательную власть посредством принятия, изменения и отмены кодексов, федеральных законов и иных актов в пределах своей компетенции."},{"type":"paragraph","number":"3","text":"Государственная Дума осуществляет свои полномочия самостоятельно и не вправе вмешиваться в рассмотрение конкретных судебных дел, расследование конкретных уголовных дел или оперативно-розыскную деятельность государственных органов."}]},{"type":"article","number":"44","title":"Состав Государственной Думы","children":[{"type":"paragraph","number":"1","text":"Государственная Дума РО формируется исключительно из представителей государственных организаций, а также представителей политических партий обладающих правом постоянного представительства в соответствии с федеральным конституционным законом."},{"type":"paragraph","number":"2","text":"Перечень государственных организаций, имеющих право постоянного представительства в Государственной Думе, а также количество закрепленных за ними депутатских мандатов устанавливаются федеральным конституционным законом."},{"type":"paragraph","number":"3","text":"Государственную организацию представляет ее руководитель либо иной сотрудник, письменно уполномоченный руководителем. Руководитель вправе отозвать или заменить представителя в установленном законом порядке."},{"type":"paragraph","number":"4","text":"Депутатский мандат возникает исключительно в связи с представительством государственной организации и прекращается при отзыве или замене ее представителя либо в иных случаях, установленных федеральным конституционным законом."},{"type":"paragraph","number":"5","text":"Каждый депутат Государственной Думы обладает одним голосом. Одно лицо не может одновременно занимать два или более депутатских мандата."},{"type":"paragraph","number":"6","text":"Председателем Государственной Думы является Вице Премьер-министр РО, это исключительный случай, когда одно лицо осуществляет полномочия двумя ветвями власти. Заместителями председателя является уполномоченные лица, назначаемые Вице Премьер-министром РО."}]},{"type":"article","number":"45","title":"Статус депутатов Государственной Думы","children":[{"type":"paragraph","number":"1","text":"Член Государственной Думы обязан лично участвовать в голосовании и действовать в пределах Конституции и федерального законодательства."},{"type":"paragraph","number":"2","text":"Представитель государственной организации сохраняет принадлежность к соответствующей организации, однако участие в Государственной Думе не предоставляет ему права использовать ее служебные полномочия для давления на иных депутатов Государственной Думы."},{"type":"paragraph","number":"3","text":"Депутат Государственной Думы не вправе использовать депутатский мандат для дачи обязательных распоряжений государственным органам и их сотрудникам вне полномочий, прямо установленных законом."},{"type":"paragraph","number":"4","text":"Представители суда, прокуратуры, Следственного комитета и правоохранительных органов не вправе использовать участие в Государственной Думе для влияния на конкретное судебное разбирательство, уголовное дело, проверку или оперативное мероприятие."}]},{"type":"article","number":"46","title":"Полномочия Государственной Думы","children":[{"type":"paragraph","number":"1","text":"Государственная Дума принимает, изменяет и отменяет кодексы и федеральные законы."},{"type":"paragraph","number":"2","text":"Государственная Дума рассматривает проекты нормативных правовых актов, поступившие в порядке законодательной инициативы."},{"type":"paragraph","number":"3","text":"Государственная Дума участвует в процедуре изменения Конституции в порядке, установленном настоящей Конституцией и федеральным конституционным законом."},{"type":"paragraph","number":"4","text":"Государственная Дума вправе запрашивать у государственных органов сведения, необходимые для законодательной деятельности, если предоставление таких сведений не нарушает режим государственной, следственной, судебной или иной охраняемой законом тайны."},{"type":"paragraph","number":"5","text":"Государственная Дума осуществляет иные полномочия, определенные федеральным законом."}]},{"type":"article","number":"47","title":"Законодательная инициатива","children":[{"type":"paragraph","number":"1","text":"Правом законодательной инициативы обладают Премьер-министр РО, Правительство РО, Вице Премьер-министр РО, депутаты Государственной Думы, Верховный Суд РО, Генеральный прокурор РО и Глава Следственного комитета РО."},{"type":"paragraph","number":"2","text":"Проект закона должен содержать текст предлагаемых норм и обоснование необходимости их принятия."}]},{"type":"article","number":"48","title":"Принятие решений Государственной Думой","children":[{"type":"paragraph","number":"1","text":"Порядок созыва заседаний, кворум и организация голосования устанавливаются федеральным законом и регламентом Государственной Думы."},{"type":"paragraph","number":"2","text":"Если Конституцией или федеральным конституционным законом не установлено иное, решение Государственной Думы принимается большинством голосов депутатов, участвующих в голосовании при наличии кворума."},{"type":"paragraph","number":"3","text":"Каждый депутат Государственной Думы голосует лично. Передача голоса другому лицу не допускается."}]},{"type":"article","number":"49","title":"Подписание и опубликование федеральных законов","children":[{"type":"paragraph","number":"1","text":"Принятый Государственной Думой федеральный закон направляется Премьер-министру РО."},{"type":"paragraph","number":"2","text":"Премьер-министр в течение 48 часов подписывает и направляет закон на официальное опубликование либо возвращает его в Государственная Дума с мотивированными возражениями."},{"type":"paragraph","number":"3","text":"Государственная Дума вправе преодолеть вето Премьер-министра не менее чем двумя третями голосов от установленного состава Государственной Думы. После преодоления вето Премьер-министр обязан подписать и направить закон на официальное опубликование."},{"type":"paragraph","number":"4","text":"Федеральный закон не вступает в силу до его официального опубликования, если самим законом не установлен более поздний срок вступления в силу."}]}]},{"type":"chapter","number":"V","title":"Правительство РО​","children":[{"type":"article","number":"50","title":"Статус Правительства","children":[{"type":"paragraph","number":"1","text":"Правительство РО — высший коллегиальный исполнительный орган государственного управления и государственной власти."},{"type":"paragraph","number":"2","text":"Правительство действует на основании Конституции, федерального законодательства и актов Премьер-министра."}]},{"type":"article","number":"51","title":"Состав Правительства","children":[{"type":"paragraph","number":"1","text":"В состав Правительства входят Премьер-министр РО в предусмотренных законом случаях, ВицеПремьер-министр либо иное уполномоченное лицо, федеральные министры, их заместители и иные должностные лица, определенные федеральным законом."},{"type":"paragraph","number":"2","text":"Конкретная структура Правительства определяется федеральным законом и актами, принятыми в соответствии с ним."}]},{"type":"article","number":"52","title":"Задачи Правительства","children":[{"type":"paragraph","number":"1","text":"Правительство обеспечивает исполнение законодательства, управление государственной собственностью и бюджетом, проведение единой государственной политики, функционирование государственных организаций и защиту прав граждан."},{"type":"paragraph","number":"2","text":"Правительство участвует в законодательном процессе посредством права законодательной инициативы и подготовки проектов нормативных правовых актов в пределах своей компетенции."},{"type":"paragraph","number":"3","text":"Правительство вправе проводить проверки государственных организаций в порядке, с периодичностью и в пределах, установленных федеральным законом."}]},{"type":"article","number":"53","title":"Право законодательной инициативы Правительства","children":[{"type":"paragraph","number":"1","text":"Правительство вправе разрабатывать и вносить в Государственная Дума проекты кодексов, федеральных законов и поправок к ним."},{"type":"paragraph","number":"2","text":"Законодательная инициатива Правительства должна быть мотивированной, соответствовать Конституции и установленному разграничению компетенции государственных органов."},{"type":"paragraph","number":"3","text":"Правительство не вправе самостоятельно изменять кодексы или федеральные законы посредством подзаконного акта, устанавливать уголовную ответственность либо изменять положения Конституции."}]},{"type":"article","number":"54","title":"Бюджет и имущество государства","children":[{"type":"paragraph","number":"1","text":"Правительство распоряжается государственным бюджетом и имуществом исключительно в публичных интересах."},{"type":"paragraph","number":"2","text":"Премирование государственных организаций и служащих, финансирование и иные выплаты осуществляются только в установленном функциональном и правовом порядке."},{"type":"paragraph","number":"3","text":"Отчуждение государственного имущества в личных целях запрещается."}]},{"type":"article","number":"55","title":"Контроль государственных организаций","children":[{"type":"paragraph","number":"1","text":"Правительство вправе осуществлять надзорные и организационные проверки государственных организаций в пределах своей компетенции."},{"type":"paragraph","number":"2","text":"Проверки не должны использоваться как средство давления на следствие, суд, прокуратуру или оперативную деятельность."},{"type":"paragraph","number":"3","text":"Правительство обязано реагировать на выявленные правонарушения государственных служащих и не вправе сознательно игнорировать очевидные нарушения закона."}]},{"type":"article","number":"56","title":"Внутренние акты государственных организаций","children":[{"type":"paragraph","number":"1","text":"Регламенты, инструкции, положения об отделах и иные внутренние акты государственных организаций подлежат утверждению в порядке, установленном Правительством."},{"type":"paragraph","number":"2","text":"Внутренний акт не может расширять компетенцию организации сверх федерального закона."}]},{"type":"article","number":"57","title":"Адвокатская деятельность и лицензирование","children":[{"type":"paragraph","number":"1","text":"Правительство обеспечивает выдачу и учет адвокатских лицензий в порядке, установленном федеральным законом."},{"type":"paragraph","number":"2","text":"Стоимость и условия лицензирования устанавливаются нормативными актами Правительства в пределах федерального законодательства."},{"type":"paragraph","number":"3","text":"Государственные органы обязаны обеспечивать реальную возможность осуществления права задержанного на защиту."}]},{"type":"article","number":"58","title":"Невмешательство Правительства в расследование","children":[{"type":"paragraph","number":"1","text":"Правительство осуществляет общее руководство исполнительной властью, не вмешиваясь в расследование конкретных уголовных дел и оперативную деятельность правоохранительных органов."},{"type":"paragraph","number":"2","text":"Исключения допускаются только на основании Конституции или федерального закона и не могут означать указание на заведомо незаконный результат расследования."}]}]},{"type":"chapter","number":"VI","title":"Судебная власть​","children":[{"type":"article","number":"59","title":"Осуществление правосудия","children":[{"type":"paragraph","number":"1","text":"Правосудие в РО осуществляется исключительно судами."},{"type":"paragraph","number":"2","text":"Судебная власть самостоятельна и независима при разрешении конкретных дел."}]},{"type":"article","number":"60","title":"Система судов","children":[{"type":"paragraph","number":"1","text":"Судебную систему РО образуют Верховный Суд РО, Кутузовский районный суд и мировые судьи."},{"type":"paragraph","number":"2","text":"Верховный Суд РО является высшим судебным органом РО."},{"type":"paragraph","number":"3","text":"Мировые судьи являются нижним звеном судебной системы и рассматривают в первой инстанции дела небольшой сложности и иные категории дел, прямо отнесенные к их компетенции федеральным законодательством. Судебные акты мировых судей могут быть обжалованы в Кутузовский районный суд."},{"type":"paragraph","number":"4","text":"Кутузовский районный суд является основным судом первой инстанции по делам, не отнесенным к компетенции мировых судей или Верховного Суда, а также вышестоящим судом по отношению к мировым судьям. Верховный Суд РО является вышестоящим судом по отношению к Кутузовскому районному суду и осуществляет пересмотр его судебных актов в случаях и порядке, установленных федеральным законодательством."},{"type":"paragraph","number":"5","text":"Создание иных судов допускается федеральным конституционным законом."}]},{"type":"article","number":"61","title":"Состав Верховного Суда","children":[{"type":"paragraph","number":"1","text":"Верховный Суд возглавляет Председатель Верховного Суда."},{"type":"paragraph","number":"2","text":"При Председателе Верховного Суда могут осуществлять полномочия не более трёх Верховных судей."},{"type":"paragraph","number":"3","text":"Порядок назначения, освобождения и дисциплинарной ответственности судей устанавливается федеральным конституционным законом."}]},{"type":"article","number":"62","title":"Независимость и законность решений суда","children":[{"type":"paragraph","number":"1","text":"Судья обязан разрешать дело объективно, беспристрастно и на основании закона."},{"type":"paragraph","number":"2","text":"Заведомо неправосудное решение подлежит отмене или пересмотру в установленном законом порядке и может повлечь ответственность судьи."},{"type":"paragraph","number":"3","text":"Никто не вправе оказывать давление на судью с целью получения заранее определенного решения."}]},{"type":"article","number":"63","title":"Обязательность судебных актов","children":[{"type":"paragraph","number":"1","text":"Вступившие в силу судебные акты обязательны для граждан, организаций и государственных органов."},{"type":"paragraph","number":"2","text":"Неисполнение судебного акта влечет ответственность, установленную законом."},{"type":"paragraph","number":"3","text":"Суд вправе устанавливать срок исполнения своего акта в пределах федерального законодательства."}]},{"type":"article","number":"64","title":"Судебный контроль за государственными органами","children":[{"type":"paragraph","number":"1","text":"Суд вправе признавать незаконными действия и решения государственных органов и должностных лиц, отменять незаконные индивидуальные акты, присуждать компенсацию и применять иные способы защиты, предусмотренные законом."},{"type":"paragraph","number":"2","text":"В предусмотренных законом случаях суд вправе временно отстранить или окончательно снять с должности руководителя государственной организации или иное должностное лицо."}]},{"type":"article","number":"65","title":"Открытость судопроизводства","children":[{"type":"paragraph","number":"1","text":"Судебные разбирательства являются открытыми, кроме случаев, когда закрытое заседание необходимо для защиты государственной тайны, участников процесса либо иных охраняемых законом интересов."},{"type":"paragraph","number":"2","text":"Место и организационный порядок проведения судебных заседаний определяются судебным законодательством."}]},{"type":"article","number":"66","title":"Состязательность и право быть услышанным","children":[{"type":"paragraph","number":"1","text":"Судопроизводство основывается на состязательности и равноправии сторон."},{"type":"paragraph","number":"2","text":"Лицам, участвующим в деле, должна быть предоставлена разумная возможность представить доказательства, возражения и правовую позицию."}]},{"type":"article","number":"67","title":"Обжалование судебных актов","children":[{"type":"paragraph","number":"1","text":"Судебные акты могут быть обжалованы в порядке, установленном процессуальным законодательством."},{"type":"paragraph","number":"2","text":"Подача жалобы сама по себе не приостанавливает исполнение акта, если иное не предусмотрено законом или решением компетентного суда."}]}]},{"type":"chapter","number":"VII","title":"Прокуратура РО и Следственный комитет РО​","children":[{"type":"article","number":"68","title":"Прокуратура РО","children":[{"type":"paragraph","number":"1","text":"Прокуратура РО осуществляет надзор за соблюдением Конституции и исполнением федерального законодательства, защищает публичный интерес и участвует в уголовном судопроизводстве в установленных законом формах."},{"type":"paragraph","number":"2","text":"Прокурор при осуществлении процессуальных полномочий обязан действовать объективно и независимо от незаконных указаний."},{"type":"paragraph","number":"3","text":"В организационном отношении прокуратура РО входит во фракцию Правительства РО. Такое организационное включение не предоставляет Правительству права вмешиваться в конкретную прокурорскую проверку, судебное производство с участием прокурора либо предопределять содержание акта прокурорского реагирования."},{"type":"paragraph","number":"4","text":"Генеральный прокурор РО назначается на должность и освобождается от должности Премьер-министром РО."}]},{"type":"article","number":"69","title":"Прокурорский надзор за задержанием государственных служащих","children":[{"type":"paragraph","number":"1","text":"Федеральный закон может устанавливать специальный порядок задержания и помещения под стражу действующих государственных служащих, предусматривающий обязательное участие или уведомление прокурора."},{"type":"paragraph","number":"2","text":"Исключения из такого порядка допускаются при наличии судебного акта, законного ордера, особого правового режима либо иных прямо предусмотренных законом оснований."}]},{"type":"article","number":"70","title":"Следственный комитет РО","children":[{"type":"paragraph","number":"1","text":"Следственный комитет РО является федеральным следственным органом, осуществляющим предварительное расследование уголовных дел, отнесенных к его подследственности."},{"type":"paragraph","number":"2","text":"Следственный комитет РО является самостоятельным федеральным государственным органом и не входит в систему Прокуратуры РО. Прокуратура не осуществляет организационное или административное руководство Следственным комитетом. Взаимодействие между ними осуществляется исключительно в формах, предусмотренных федеральным законодательством."}]},{"type":"article","number":"71","title":"Основные задачи Следственного комитета","children":[{"type":"paragraph","number":"1","text":"К основным задачам Следственного комитета относятся возбуждение уголовных дел при наличии законных оснований, проведение следственных действий, собирание и закрепление доказательств, предъявление обвинения и направление оконченного уголовного дела в суд для разрешения вопроса об утверждении обвинительного заключения и ответственности обвиняемого."},{"type":"paragraph","number":"2","text":"Следственный комитет не вправе возбуждать дело, предъявлять обвинение или применять меры процессуального принуждения при отсутствии достаточных законных оснований."}]},{"type":"article","number":"72","title":"Руководство предварительным расследованием","children":[{"type":"paragraph","number":"1","text":"По уголовным делам, находящимся в производстве Следственного комитета, Следственный комитет руководит предварительным расследованием."},{"type":"paragraph","number":"2","text":"В пределах расследуемого уголовного дела уполномоченный следователь вправе давать обязательные к исполнению поручения органам Министерства внутренних дел, если такие поручения законны, конкретны и относятся к предмету расследования."}]},{"type":"article","number":"73","title":"Следственные действия","children":[{"type":"paragraph","number":"1","text":"Допрос, осмотр места происшествия, обыск, выемка, следственный эксперимент и иные следственные действия проводятся только при наличии предусмотренных законом оснований."},{"type":"paragraph","number":"2","text":"Вмешательство в права граждан при проведении следственного действия должно быть соразмерно его законной цели."}]},{"type":"article","number":"74","title":"Взаимодействие Следственного комитета","children":[{"type":"paragraph","number":"1","text":"Следственный комитет взаимодействует с Министерством внутренних дел, ГИБДД, Федеральной службой безопасности, прокуратурой и иными государственными органами в пределах расследуемого дела и компетенции соответствующих органов."},{"type":"paragraph","number":"2","text":"Следственный комитет не осуществляет обычное патрулирование, рейды и иные мероприятия, не относящиеся к его следственной компетенции, кроме совместных мероприятий, предусмотренных законом."}]},{"type":"article","number":"75","title":"Объективность расследования","children":[{"type":"paragraph","number":"1","text":"Процессуальное решение следователя должно быть объективным, мотивированным и беспристрастным."},{"type":"paragraph","number":"2","text":"Запрещаются злоупотребление полномочиями, фабрикация доказательств и давление на участников уголовного процесса."}]},{"type":"article","number":"76","title":"Акты прокуратуры и Следственного комитета","children":[{"type":"paragraph","number":"1","text":"Законные постановления, требования и поручения прокуратуры и Следственного комитета обязательны для адресатов в пределах компетенции соответствующего органа."},{"type":"paragraph","number":"2","text":"Акты прокуратуры и Следственного комитета могут быть обжалованы в суд или вышестоящему должностному лицу в порядке, установленном законом."}]}]},{"type":"chapter","number":"VIII","title":"Правоохранительные органы, органы государственной безопасности и Вооружённые Силы​","children":[{"type":"article","number":"77","title":"Общие принципы деятельности силовых государственных организаций","children":[{"type":"paragraph","number":"1","text":"К силовым государственным организациям относятся органы внутренних дел, ГИБДД, Федеральная служба безопасности, Вооружённые Силы и иные органы, прямо отнесенные к ним федеральным законом."},{"type":"paragraph","number":"2","text":"Их сотрудники обязаны действовать в пределах компетенции, соблюдать права граждан, требования к служебной идентификации и установленный порядок применения государственного функционала."},{"type":"paragraph","number":"3","text":"Полномочия одной организации не могут произвольно присваиваться другой организацией."}]},{"type":"article","number":"78","title":"Министерство внутренних дел","children":[{"type":"paragraph","number":"1","text":"Органы Министерства внутренних дел обеспечивают общественный порядок и безопасность на территории муниципальных образований, осуществляют патрулирование, реагирование на вызовы, задержание правонарушителей, оперативно-розыскные мероприятия, конвоирование и охрану мест происшествий в пределах закона."},{"type":"paragraph","number":"2","text":"Министерство внутренних дел оказывает содействие Следственному комитету и Федеральной службе безопасности при проведении специальных мероприятий и исполняет законные поручения Следственного комитета по расследуемым им уголовным делам."},{"type":"paragraph","number":"3","text":"Обращения граждан подлежат рассмотрению в сроки, установленные федеральным законодательством."}]},{"type":"article","number":"79","title":"Государственная инспекция безопасности дорожного движения","children":[{"type":"paragraph","number":"1","text":"ГИБДД осуществляет контроль безопасности дорожного движения, пресечение нарушений дорожного законодательства и иные полномочия, установленные федеральным законом."},{"type":"paragraph","number":"2","text":"При выявлении признаков преступления, выходящего за пределы компетенции ГИБДД, материалы без необоснованной задержки передаются Министерству внутренних дел, Следственному комитету или Федеральной службе безопасности в зависимости от подследственности и компетенции."}]},{"type":"article","number":"80","title":"Федеральная служба безопасности","children":[{"type":"paragraph","number":"1","text":"Федеральная служба безопасности является федеральным правоохранительным органом, осуществляющим внутреннюю разведку, контрразведывательную и антитеррористическую деятельность, а также противодействие преступлениям федерального уровня и преступлениям против государственной безопасности."},{"type":"paragraph","number":"2","text":"Федеральная служба безопасности подчиняется Премьер-министру РО и Министру юстиции в пределах установленной компетенции."},{"type":"paragraph","number":"3","text":"Федеральная служба безопасности вправе координировать специальные мероприятия по преступлениям федерального характера и угрозам государственной безопасности, при необходимости привлекая иные государственные организации."}]},{"type":"article","number":"81","title":"Дополнительная компетенция Федеральной службы безопасности","children":[{"type":"paragraph","number":"1","text":"Федеральная служба безопасности осуществляет формирование материалов уголовных и оперативных производств в пределах своей компетенции, выявляет коррупционные преступления в государственных органах и проводит специальные операции."},{"type":"paragraph","number":"2","text":"Обработка правонарушений регионального уровня Федеральной службой безопасности допускается по законному запросу старшего состава Министерства внутренних дел или ГИБДД, при отсутствии возможности их самостоятельной обработки либо при наличии иной предусмотренной законом веской причины."}]},{"type":"article","number":"82","title":"Взаимодействие государственных организаций","children":[{"type":"paragraph","number":"1","text":"Следственный комитет руководит предварительным расследованием уголовных дел, находящихся в его производстве."},{"type":"paragraph","number":"2","text":"Министерство внутренних дел обеспечивает общественный порядок и оказывает содействие Следственному комитету и Федеральной службе безопасности."},{"type":"paragraph","number":"3","text":"ГИБДД осуществляет компетенцию в сфере дорожной безопасности и передает материалы по признакам преступлений компетентному органу."},{"type":"paragraph","number":"4","text":"Федеральная служба безопасности координирует мероприятия по угрозам федерального уровня и государственной безопасности."},{"type":"paragraph","number":"5","text":"Государственные органы обязаны обмениваться необходимыми материалами и содействовать друг другу только в пределах закона и своей компетенции."}]},{"type":"article","number":"83","title":"Вооружённые Силы РО","children":[{"type":"paragraph","number":"1","text":"Вооруженные Силы предназначены для защиты военных объектов, охраны вооружения, проведения военной подготовки и выполнения задач в условиях чрезвычайного или военного положения."},{"type":"paragraph","number":"2","text":"Вооруженные Силы подчиняются Премьер-министру РО, Министерству внутренних дел и военному командованию в установленной иерархии."},{"type":"paragraph","number":"3","text":"Привлечение Вооруженных Сил к мероприятиям внутренней безопасности допускается исключительно в случаях, предусмотренных федеральным законодательством, либо по законному решению Премьер-министра или Правительства."}]},{"type":"article","number":"84","title":"Задержание военнослужащими","children":[{"type":"paragraph","number":"1","text":"Военнослужащие вправе задерживать граждан на военных объектах и прилегающих режимных территориях в случаях совершения противоправных действий, а также в иных прямо предусмотренных законом случаях."},{"type":"paragraph","number":"2","text":"Задержанное лицо подлежит передаче компетентному правоохранительному органу без необоснованной задержки, если федеральным законом не предусмотрено иное."}]},{"type":"article","number":"85","title":"Видеофиксация и доказательственная сохранность","children":[{"type":"paragraph","number":"1","text":"Федеральным законом устанавливаются случаи обязательной видеофиксации задержания, ареста, обыска, изъятия имущества, выдачи или снятия розыска, процессуальных действий и иных значимых действий государственных служащих."},{"type":"paragraph","number":"2","text":"Запись должна сохраняться в установленный законом срок и предоставляться суду, прокуратуре или иному уполномоченному органу при законном запросе."},{"type":"paragraph","number":"3","text":"Фальсификация, необоснованное уничтожение или сокрытие обязательной видеозаписи влечёт ответственность."}]}]},{"type":"chapter","number":"IX","title":"Особые правовые режимы​","children":[{"type":"article","number":"86","title":"Чрезвычайное и военное положение","children":[{"type":"paragraph","number":"1","text":"Чрезвычайное или военное положение вводится в порядке, установленном федеральным конституционным законом."},{"type":"paragraph","number":"2","text":"Акт о введении особого режима должен определять основания, территорию, срок действия, временные полномочия государственных органов и перечень допустимых ограничений прав."}]},{"type":"article","number":"87","title":"Временное расширение полномочий","children":[{"type":"paragraph","number":"1","text":"На период чрезвычайного или военного положения государственным органам могут предоставляться дополнительные полномочия, необходимые для устранения угрозы."},{"type":"paragraph","number":"2","text":"Такие полномочия не могут использоваться для отмены Конституции, устранения судебной защиты, легализации заведомо незаконного насилия или присвоения полномочий, не связанных с целями особого режима."}]},{"type":"article","number":"88","title":"Использование силовых организаций в особых условиях","children":[{"type":"paragraph","number":"1","text":"В условиях чрезвычайного или военного положения Премьер-министр и Правительство вправе координировать совместные действия Министерства внутренних дел, Федеральной службы безопасности, Следственного комитета и Вооружённых Сил в пределах федерального законодательства."},{"type":"paragraph","number":"2","text":"Процессуальное руководство уголовными делами при этом сохраняется за органом, которому дело подследственно."}]},{"type":"article","number":"89","title":"Гарантии законности при особом режиме","children":[{"type":"paragraph","number":"1","text":"Введение особого правового режима не освобождает государственные органы и должностных лиц от обязанности соблюдать закон."},{"type":"paragraph","number":"2","text":"Действия и решения, принятые в период особого режима, могут быть обжалованы в суд и прокуратуру, если федеральным законом прямо не установлен особый порядок обжалования."}]}]},{"type":"chapter","number":"X","title":"Конституционные поправки и заключительные положения​","children":[{"type":"article","number":"90","title":"Инициатива изменения Конституции","children":[{"type":"paragraph","number":"1","text":"Предложения о внесении изменений в Конституцию могут вносить Премьер-министр РО, Государственная Дума РО, Правительство РО, Верховный Суд РО, Генеральный прокурор РО и Глава Следственного комитета РО."},{"type":"paragraph","number":"2","text":"Порядок рассмотрения конституционных поправок устанавливается федеральным конституционным законом."}]},{"type":"article","number":"91","title":"Пределы конституционных поправок","children":[{"type":"paragraph","number":"1","text":"Поправка не может отменять судебную защиту, презумпцию невиновности, запрет произвольного задержания, право на защиту либо придавать обратную силу норме, устанавливающей или усиливающей ответственность."},{"type":"paragraph","number":"2","text":"Поправка не может предоставлять одному органу неограниченное право присваивать полномочия других государственных органов."}]},{"type":"article","number":"92","title":"Обеспечение конституционной законности","children":[{"type":"paragraph","number":"1","text":"Нормативные правовые акты и внутренние регламенты государственных организаций подлежат приведению в соответствие с настоящей Конституцией."},{"type":"paragraph","number":"2","text":"При выявлении противоречия между нормативными актами применяется акт большей юридической силы. Окончательное разрешение спора о конституционности акта относится к компетенции Верховного Суда."}]},{"type":"article","number":"93","title":"Вступление в силу","children":[{"type":"paragraph","number":"1","text":"Конституция вступает в силу с момента ее официального опубликования и утверждения в установленном порядке."},{"type":"paragraph","number":"2","text":"Ранее принятые нормативные акты применяются постольку, поскольку они не противоречат настоящей Конституции."},{"type":"paragraph","number":"3","text":"Государственные органы обязаны привести действующие законы, кодексы, указы, регламенты и внутренние инструкции в соответствие с настоящей Конституцией."}]}]}]};
